 15→/// Interactive terminal UI implementation.
 16→pub struct TerminalUI {
 17→    term: Term,
 18→    theme: BivvyTheme,
 19→    mode: OutputMode,
 20→}
 21→
 22→impl TerminalUI {
 23→    /// Create a new terminal UI.
 24→    pub fn new(mode: OutputMode) -> Self {
 25→        let theme = if should_use_colors() {
 26→            BivvyTheme::new()
 27→        } else {
 28→            BivvyTheme::plain()
 29→        };
 30→
 31→        Self {
 32→            term: Term::stdout(),
 33→            theme,
 34→            mode,
 35→        }
 36→    }
 37→}
