456→#[cfg(test)]
457→mod tests {
458→    use super::*;
459→    use crate::ui::MockUI;
460→    use tempfile::TempDir;
461→
462→    fn create_test_store(temp: &TempDir) -> FeedbackStore {
463→        FeedbackStore::new(temp.path().join("feedback.jsonl"))
464→    }
465→
466→    #[test]
467→    fn list_empty_feedback() {
468→        let temp = TempDir::new().unwrap();
469→        let store = create_test_store(&temp);
470→        let mut ui = MockUI::new();
471→
472→        let result = list_feedback(&store, None, None, false, &mut ui).unwrap();
473→        assert_eq!(result, 0);
474→    }
475→
